  "codebook": {
    "definition": "Credit-claiming occurs when a senator explicitly or implicitly takes personal responsibility for a specific action, outcome, or benefit, often by highlighting their direct involvement, advocacy, or role in securing funding, legislation, or recognition.",
    "clarification": "Credit-claiming is identified when the senator uses language that directly links their efforts to a tangible result, such as securing funds, passing legislation, or achieving a specific outcome. This includes phrases like 'I secured,' 'I helped,' 'I authored,' or 'I fought for.' It may also involve the senator taking pride in a program, initiative, or recognition that bears their name or is directly tied to their actions.",
    "positive_examples": [
      {
        "document_id": "89",
        "explanation": "Senator Dorgan explicitly states that he authored legislation and secured a designation for Bismarck State College, directly linking his actions to the outcome. This is a clear example of credit-claiming."
      },
      {
        "document_id": "2318",
        "explanation": "Senator Durbin explicitly states that he helped secure an expedited environmental review and facilitated the return of the South Suburban Airport project to the national priority list, taking direct credit for these actions."
      },
      {
        "document_id": "3482",
        "explanation": "Senators Mikulski and Cardin announce federal funding for firefighters and explicitly state their roles in fighting for and securing the funds, demonstrating credit-claiming."
      }
    ],
    "negative_clarification": "Credit-claiming does not occur when a senator merely discusses an issue, criticizes others, or expresses support or concern without directly linking their actions to a specific outcome. Statements that are purely informational, analytical, or critical do not qualify as credit-claiming unless they explicitly or implicitly tie the senator's efforts to a result.",
